fn solve(nums: Vec<i8>) -> Vec<char> {
    // We expect exactly three numbers.
    assert!(nums.len() == 3, "Expected exactly three integers");

    // Sort them in non-decreasing order.
    let mut v = nums;
    v.sort_unstable();
    let a = v[0];
    let b = v[1];
    let c = v[2];

    // Check the four conditions for "YES".
    let yes = 
        // at least one of the numbers is 1
        a == 1
        // at least two of the numbers are 2
        || (a == 2 && b == 2)
        // exactly (2, 4, 4)
        || (a == 2 && b == 4 && c == 4)
        // exactly (3, 3, 3)
        || (a == 3 && b == 3 && c == 3);

    if yes {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}

